    COALESCE(SUM(d.runs_extras), 0)::int AS extras,
    COALESCE(SUM(d.extra_byes), 0)::int AS "byeRuns",
    COALESCE(SUM(d.extra_legbyes), 0)::int AS "legByeRuns",
    COALESCE(SUM(d.extra_wides), 0)::int AS "wideRuns",
